def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in (3, 4, 9):
                neighbors = {}
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < len(grid) and 0 <= cc < len(row):
                        color = grid[rr][cc]
                        if color in (3, 4, 9):
                            neighbors[color] = neighbors.get(color, 0) + 1
                if neighbors:
                    out[r][c] = max(neighbors, key=neighbors.get)
    return out
